#!/usr/bin/env python3
"""Verify quarter twist is integral on linked normal pullback, not individual divisor loops."""
from hashlib import sha256
from pathlib import Path
import json
import sympy as s
ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/quarter_twist_is_integral_only_on_the_linked_normal_curve.md';LIFTS=ROOT/'research/voevodsky/results/two_wall_labelled_kummer_lifts.json';MONO=ROOT/'research/voevodsky/results/relative_combined_wall_monodromy.json';RESULT=ROOT/'research/voevodsky/results/quarter_twist_linked_curve_integrality.json';RB=s.Matrix([[1,0,0],[0,0,0],[1,0,0]]);RC=s.Matrix([[0,1,1],[0,0,0],[0,1,1]]);RE=s.Matrix([[1,-1,-1],[-1,1,1],[0,0,0]]);I=s.eye(3);MB=I+(s.I-1)*RB;MC=I+(s.I-1)*RC;ME=I-RE;Req=RB+RC+RE;W=s.Matrix([[-1,1,0],[1,0,-1],[0,1,1]]);Mlinked=s.simplify(W*s.diag(-1,-1,1)*W.inv());comm=lambda A,B:A*B-B*A;checks={'RB_idempotent':RB**2==RB,'RC_idempotent':RC**2==RC,'RE_scaled_idempotent':RE**2==2*RE,'MB_nonrational':any(x.has(s.I) for x in MB),'MC_nonrational':any(x.has(s.I) for x in MC),'ME_integral':all(x.q==1 for x in ME),'residues_noncommuting':all(comm(A,B)!=s.zeros(3) for A,B in [(RB,RC),(RB,RE),(RC,RE)]),'linked_residue_exact':Req==s.Matrix([[2,0,0],[-1,1,1],[1,1,1]]),'linked_monodromy_integral':all(x.q==1 for x in Mlinked),'linked_lift_source':json.loads(LIFTS.read_text(encoding='utf-8'))['common_pullback']=={'B':'E','C':'E','Erel':'2E'},'prior_integral_conjugacy':json.loads(MONO.read_text(encoding='utf-8'))['checks']['integral_conjugacy'],'ambient_integrality_rejected':'does not extend to independent loops' in PACKET.read_text(encoding='utf-8'),'contour_gate':'Physical authority for that linked contour remains absent' in PACKET.read_text(encoding='utf-8')};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.quarter-twist-linked-curve-integrality.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'lifts_result_sha256':sha256(LIFTS.read_bytes()).hexdigest(),'monodromy_result_sha256':sha256(MONO.read_bytes()).hexdigest(),'individual_monodromy_coefficients':'Z[i] required for B,C','linked_monodromy':[[int(x) for x in Mlinked.row(i)] for i in range(3)],'checks':checks,'passed':all(checks.values()),'disposition':{'ambient_rank3_integral_local_system':'obstructed','linked_normal_rank3_integral_monodromy':'verified conditionally','physical_linked_contour':'missing'}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
